<script setup lang="ts">
import UserAvatar from '@/components/UserAvatar.vue'
import BrandLogo from '@/components/BrandLogo.vue'
import {showToast} from '@/lib/toast'
import {clearLegacyTelegramFlags} from '@/lib/telegramLogin'
import {ref,computed,onMounted,onBeforeUnmount,watch} from 'vue'
import {useRouter,useRoute} from 'vue-router'
import {UserRound, Gem, ShieldCheck, SlidersHorizontal, LogOut, ArrowUpRight, Check, Wallet, Link2, Camera, Upload, Send, MonitorSmartphone, ChevronRight, ShieldAlert, Film} from 'lucide-vue-next'
import {useAuthStore} from '@/stores/auth'
import {tr,language,setLanguage} from '@/i18n'
import {accountApi as api} from '@/accountApi'
import AccountSecurity from '@/components/AccountSecurity.vue'
import TwoFactorStatus from '@/components/TwoFactorStatus.vue'
import BillingPanel from '@/components/BillingPanel.vue'
import DesktopPlayerCard from '@/components/DesktopPlayerCard.vue'
const auth=useAuthStore(),router=useRouter(),route=useRoute()
const tabs=computed(()=>[{id:'profile',label:tr('Профиль','Profile'),icon:UserRound},{id:'billing',label:tr('PRO подписка и оплата','PRO & Billing'),icon:Gem},{id:'player',label:'KINOSOTA Player',icon:MonitorSmartphone},{id:'security',label:tr('Безопасность и 2FA','Security & 2FA'),icon:ShieldCheck},{id:'settings',label:tr('Настройки','Settings'),icon:SlidersHorizontal}])
function routeTab(){const tab=route.query.tab;return typeof tab==='string'&&tabs.value.some(t=>t.id===tab)?tab:route.query.player_code||route.hash==='#desktop-player'?'player':'profile'}
const active=ref(routeTab()),account=ref<any>(null),busy=ref(false),error=ref(''),message=ref(''),displayName=ref(''),username=ref(''),email=ref(''),password=ref(''),otp=ref(''),notifications=ref(false),link=ref<any>(null),avatarVersion=ref(0)
const sessions=ref<any[]|null>(null),sessionsError=ref(false)
async function loadSessions(){sessionsError.value=false;try{const rows=await api('/account/sessions');if(!disposed)sessions.value=Array.isArray(rows)?rows:null;sessionsError.value=!Array.isArray(rows)}catch{if(!disposed){sessions.value=null;sessionsError.value=true}}}
function openSecurity(){active.value='security';requestAnimationFrame(()=>document.getElementById('panel-security')?.scrollIntoView({block:'start'}))}
const identityChanged=computed(()=>!!account.value?.password_login_available&&(username.value!==account.value.username||email.value!==account.value.email))
const sectionTitle=computed(()=>tabs.value.find(t=>t.id===active.value)?.label||tr('Профиль','Profile'))
watch(()=>[route.query.tab,route.query.player_code,route.hash],()=>{active.value=routeTab()})
watch(active,value=>{if(value!==routeTab())void router.push({path:'/profile',query:{...route.query,tab:value},hash:''})})
let disposed=false
const avatar=computed(()=>account.value?.avatar_url?account.value.avatar_url+'?v='+avatarVersion.value:'/avatars/'+(account.value?.avatar_preset||0)+'.svg')
const isPro=computed(()=>account.value?.subscription_status&&account.value.subscription_status!=='free'&&account.value.subscription_status!=='expired'&&account.value.subscription_status!=='churned')
async function load(){const a=await api('/account');if(disposed)return;account.value=a;displayName.value=a.display_name;username.value=a.username;email.value=a.email;notifications.value=a.telegram_notifications;setLanguage(a.language);avatarVersion.value++;await auth.fetchCurrentUser();await loadSessions()}
async function action(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';message.value='';try{await fn()}catch(e:any){error.value=e.message}finally{busy.value=false;password.value='';otp.value=''}}
function tabKey(event:KeyboardEvent){const ids=tabs.value.map(t=>t.id);let index=ids.indexOf(active.value);if(['ArrowDown','ArrowRight','ArrowUp','ArrowLeft','Home','End'].includes(event.key)){event.preventDefault();index=event.key==='Home'?0:event.key==='End'?ids.length-1:(index+(['ArrowDown','ArrowRight'].includes(event.key)?1:ids.length-1))%ids.length;active.value=ids[index]!;document.getElementById('tab-'+active.value)?.focus()}}
function saveProfile(){action(async()=>{await api('/account/profile','PATCH',{display_name:displayName.value,...(account.value.password_login_available?{username:username.value,email:email.value}:{}),current_password:password.value},otp.value);await load();message.value=tr('Профиль обновлён.','Profile updated.')})}
function preset(n:number){action(async()=>{await api('/account/avatar/preset','PUT',{preset:n});await load();message.value=tr('Аватар обновлён.','Avatar updated.')})}
function upload(e:Event){const input=e.target as HTMLInputElement,file=input.files?.[0];if(!file)return;if(file.size>2*1024*1024){error.value=tr('Максимальный размер — 2 МБ.','Maximum file size is 2 MB.');input.value='';return}action(async()=>{const form=new FormData();form.append('file',file);await api('/account/avatar','POST',form);input.value='';await load();message.value=tr('Аватар обновлён.','Avatar updated.')})}
function saveSettings(){action(async()=>{await api('/account/settings','PUT',{language:language.value,telegram_notifications:notifications.value});message.value=tr('Настройки сохранены.','Settings saved.')})}
function startTelegram(){action(async()=>{link.value=await api('/account/telegram/start','POST',{})})}
function finishTelegram(){action(async()=>{const r=await api('/account/telegram/complete','POST',{state:link.value.state});if(r.status==='linked'){link.value=null;await load()}else message.value=tr('Сначала подтвердите привязку в боте.','Confirm the link in the bot first.')})}
function unlinkTelegram(){
 if(!window.confirm(account.value.password_login_available?tr('Отвязать Telegram? Вы останетесь в аккаунте.','Unlink Telegram? You will stay signed in.'):tr('Отвязать Telegram и выйти? Без пароля доступ к этому аккаунту будет потерян.','Unlink Telegram and sign out? Without a password, access to this account will be lost.')))return
 action(async()=>{
  const r=await api('/account/telegram/unlink','POST',{});link.value=null;clearLegacyTelegramFlags()
  if(r.logout){
   auth.setToken(null);auth.user.value=null
   showToast(tr('Вы вышли из аккаунта. Чтобы войти под другим номером Telegram, нажмите "Отключить" в сервисном сообщении от Telegram','You have signed out. To sign in with another Telegram number, select "Disconnect" in the service message from Telegram'))
   await router.replace('/');return
  }
  await load();message.value=tr('Telegram отвязан.','Telegram unlinked.')
 })
}
function date(s?:string){return s?new Date(s).toLocaleDateString(language.value==='ru'?'ru-RU':'en-US',{day:'numeric',month:'short',year:'numeric'}):'—'}
function status(s:string){return ({pending:tr('Ожидает оплаты','Pending'),paid:tr('Оплачено','Paid'),expired:tr('Истёк','Expired'),refunded:tr('Возврат','Refunded'),active:tr('Активна','Active'),trial:tr('Пробная','Trial'),canceled:tr('Отменена','Canceled')})[s]||s}
async function logout(){await auth.logout();router.push('/login')}
onMounted(async()=>{if(!auth.isAuthenticated.value){router.push('/login');return}await action(load)})
onBeforeUnmount(()=>{disposed=true;password.value='';otp.value=''})
</script>
<template>
 <div class="account-page account-shell"><header class="page-intro"><div><p class="eyebrow">{{tr('ЛИЧНЫЙ КАБИНЕТ','YOUR ACCOUNT')}}</p><h1>{{sectionTitle}}</h1><p class="muted">{{tr('Управляйте аккаунтом и настройками просмотра.','Manage your account and viewing preferences.')}}</p></div><button v-if="account" class="private-badge" :class="{protected:account.two_factor_enabled}" @click="openSecurity"><ShieldCheck v-if="account.two_factor_enabled" :size="20"/><ShieldAlert v-else :size="20"/>{{account.two_factor_enabled?tr('2FA включена','2FA enabled'):tr('2FA не настроена','2FA not configured')}}</button></header>
 <div class="account-layout"><aside class="account-sidebar"><div class="sidebar-frame"><router-link to="/" class="billing-brand" :title="tr('На главную','Back to home')" :aria-label="tr('KINOSOTA — на главную','KINOSOTA — home')"><BrandLogo /><span class="brand-home-hint">{{tr('На главную','Back to home')}}<ArrowUpRight :size="14" aria-hidden="true"/></span></router-link><div class="identity-mini"><UserAvatar :user="account||auth.user.value" :size="44"/><strong :title="account?.display_name||auth.user.value?.username">{{account?.display_name||auth.user.value?.username}}</strong><span class="muted">{{isPro?'PRO':tr('Базовый аккаунт','Free account')}}</span></div><nav :aria-label="tr('Разделы личного кабинета','Account sections')" role="tablist" aria-orientation="vertical"><button v-for="tab in tabs" :id="'tab-'+tab.id" :key="tab.id" role="tab" :tabindex="active===tab.id?0:-1" @keydown="tabKey" :aria-selected="active===tab.id" :aria-controls="'panel-'+tab.id" :class="{selected:active===tab.id}" @click="active=tab.id"><component :is="tab.icon" :size="19"/><span>{{tab.label}}</span><b v-if="tab.id==='security'&&account?.two_factor_enabled" class="mfa-badge">2FA ON</b></button></nav><button class="logout" @click="logout"><LogOut :size="17"/>{{tr('Выйти','Sign out')}}</button><div class="billing-sidebar-promo"><img class="sidebar-cinema" src="/account/pro-sidebar-cinema.webp" alt="" width="270" height="379"/><div class="sidebar-promo-copy"><Gem :size="25" aria-hidden="true"/><h3>{{tr('Больше,','More than')}}<br/><span>{{tr('чем просто кино.','just movies.')}}</span></h3><p>{{tr('Премиум-возможности уже включены.','Premium features are included.')}}</p></div></div></div></aside>
 <div class="account-content" :aria-busy="busy"><p v-if="error" class="notice error" role="alert">{{error}} <button v-if="!account" type="button" :disabled="busy" @click="action(load)">{{tr('Повторить загрузку','Retry loading')}}</button></p><p v-if="message" class="notice" role="status">{{message}}</p><div v-if="!account && !error" class="card">{{tr('Загружаем аккаунт…','Loading your account…')}}</div>
 <section v-else-if="account && active==='profile'" id="panel-profile" role="tabpanel" aria-labelledby="tab-profile" class="panel-stack"><div class="card avatar-card"><Film class="film-decoration" :size="130" aria-hidden="true"/><div class="profile-identity"><div class="avatar-wrap"><UserAvatar class="avatar-large" :user="account" :size="108"/><label class="camera-button" :aria-label="tr('Загрузить аватар','Upload avatar')"><Camera :size="18"/><input type="file" accept="image/jpeg,image/png,image/webp" @change="upload" :disabled="busy"/></label></div><div class="identity-copy"><h2>{{account.display_name||account.username}}</h2><p class="muted">{{tr('На KINOSOTA с','On KINOSOTA since')}} {{date(account.created_at)}}</p><span v-if="account.telegram_linked" class="status good"><Send :size="15"/>{{tr('Telegram подключён','Telegram connected')}}</span></div></div><div class="avatar-copy"><h3>{{tr('Ваш образ','Your look')}}</h3><p class="muted">{{tr('Выберите аватар или загрузите свой','Choose an avatar or upload your own')}}</p><div class="preset-gallery"><button v-for="n in 8" :key="n" :disabled="busy" :aria-label="tr('Выбрать аватар ','Choose avatar ')+n" :aria-pressed="!account.avatar_url&&account.avatar_preset===n-1" @click="preset(n-1)"><img :src="'/avatars/'+(n-1)+'.svg'" alt=""/></button></div><label class="upload-button"><Upload :size="18"/>{{tr('Загрузить изображение','Upload image')}}<input type="file" accept="image/jpeg,image/png,image/webp" @change="upload" :disabled="busy"/></label><p class="muted upload-hint">JPG, PNG, WebP · {{tr('до 2 МБ','up to 2 MB')}}</p></div></div>
 <form class="card profile-details" @submit.prevent="saveProfile"><div class="card-title"><UserRound :size="20"/><h3>{{tr('Данные аккаунта','Account details')}}</h3></div><p class="muted form-intro">{{tr('Основная информация о вашем аккаунте','Your essential account information')}}</p><label>{{tr('Никнейм','Display name')}}<input v-model="displayName" required maxlength="80" autocomplete="nickname" /></label><div class="field-grid"><label>{{tr('Логин','Username')}}<input v-model="username" :placeholder="tr('Не указан','Not provided')" required minlength="3" maxlength="50" pattern="[A-Za-z0-9_.-]+" autocomplete="username" :disabled="!account.password_login_available"/></label><label>{{tr('Электронная почта','Email')}}<input v-model="email" :placeholder="tr('Не указана','Not provided')" type="email" required autocomplete="email" :disabled="!account.password_login_available"/></label></div><p v-if="identityChanged" class="muted small">{{tr('Для смены логина или email подтвердите текущий пароль и, если включена, 2FA.','To change your username or email, confirm your current password and 2FA if enabled.')}}</p><div class="field-grid" v-if="identityChanged"><label>{{tr('Текущий пароль','Current password')}}<input v-model="password" type="password" autocomplete="current-password" maxlength="1024"/></label><label v-if="account.two_factor_enabled">{{tr('Код 2FA или резервный код','2FA or recovery code')}}<input v-model="otp" autocomplete="one-time-code" maxlength="64"/></label></div><button class="primary" :disabled="busy">{{tr('Сохранить изменения','Save changes')}}</button></form>
 <div class="card telegram-card"><span class="telegram-emblem" aria-hidden="true"><Send :size="28"/></span><div class="telegram-copy"><h3>{{tr('Связь с Telegram','Telegram connection')}}</h3><p class="telegram-handle" v-if="account.telegram_linked&&account.telegram_username">@{{account.telegram_username}}</p><p class="muted">{{account.telegram_linked?tr('Ваш аккаунт привязан к Telegram. Вы можете использовать его для входа и быстрых уведомлений.','Your Telegram account is connected for sign-in and notifications.'):tr('Привяжите Telegram для входа и уведомлений. Подтвердите запрос в боте.','Connect Telegram for sign-in and notifications. Confirm the request in the bot.')}}</p></div><div class="telegram-actions"><span class="status" :class="{good:account.telegram_linked}"><Check v-if="account.telegram_linked" :size="16"/>{{account.telegram_linked?tr('Привязан','Linked'):tr('Не привязан','Not linked')}}</span><template v-if="link"><p>{{tr('Код проверки:','Verification code:')}} <strong>{{link.verification_code}}</strong></p><a class="primary inline" :href="link.url" target="_blank" rel="noopener noreferrer">{{tr('Открыть Telegram','Open Telegram')}}<ArrowUpRight :size="15"/></a><button class="secondary" @click="finishTelegram" :disabled="busy">{{tr('Проверить привязку','Check connection')}}</button></template><button v-else class="secondary" :disabled="busy" @click="account.telegram_linked?unlinkTelegram():startTelegram()">{{account.telegram_linked?tr('Отвязать Telegram','Unlink Telegram'):tr('Привязать Telegram','Link Telegram')}}</button></div><Send class="telegram-watermark" :size="160" aria-hidden="true"/></div>
 <div class="account-summaries"><button class="card summary-card security-summary" @click="openSecurity"><span class="summary-icon" :class="{warning:!account.two_factor_enabled}"><ShieldCheck v-if="account.two_factor_enabled" :size="27"/><ShieldAlert v-else :size="27"/></span><span class="summary-copy"><strong>{{tr('Безопасность','Security')}}</strong><span>{{account.two_factor_enabled?tr('Двухфакторная защита включена.','Two-factor protection is enabled.'):tr('Двухфакторная аутентификация не настроена.','Two-factor authentication is not configured.')}}</span><b>{{account.two_factor_enabled?tr('Управлять','Manage'):tr('Настроить','Set up')}} <ArrowUpRight :size="15"/></b></span><ChevronRight :size="20"/></button><button class="card summary-card sessions-summary" @click="openSecurity"><span class="summary-icon"><MonitorSmartphone :size="27"/></span><span class="summary-copy"><strong>{{tr('Сессии','Sessions')}}</strong><span>{{sessionsError?tr('Сведения о сессиях недоступны.','Session information unavailable.'):sessions===null?tr('Загружаем сеансы…','Loading sessions…'):sessions.length?tr('Активных сеансов: ','Active sessions: ')+sessions.length:tr('Активных сеансов не найдено.','No active sessions found.')}}</span><b>{{tr('Управлять','Manage')}} <ArrowUpRight :size="15"/></b></span><ChevronRight :size="20"/></button></div></section>
 <section v-else-if="account && active==='billing'" id="panel-billing" role="tabpanel" aria-labelledby="tab-billing"><BillingPanel :account="account" @changed="load"/></section>
 <section v-else-if="account && active==='player'" id="panel-player" role="tabpanel" aria-labelledby="tab-player" class="player-panel"><DesktopPlayerCard @open-billing="active='billing'" /></section>
 <section v-else-if="account && active==='security'" id="panel-security" role="tabpanel" aria-labelledby="tab-security"><AccountSecurity @changed="load"/></section>
 <section v-else-if="account" id="panel-settings" role="tabpanel" aria-labelledby="tab-settings" class="panel-stack settings-panel"><div class="section-heading"><div><h2>{{tr('Настройте под себя','Make it yours')}}</h2><p class="muted">{{tr('Язык интерфейса и ваши предпочтения.','Your language and preferences.')}}</p></div></div><form class="settings-form" @submit.prevent="saveSettings"><div class="card preference-block language-preference"><span class="preference-icon" aria-hidden="true"><SlidersHorizontal :size="25"/></span><p class="eyebrow">{{tr('ИНТЕРФЕЙС','INTERFACE')}}</p><h3>{{tr('Язык интерфейса','Interface language')}}</h3><p class="muted">{{tr('Один язык для всей витрины. Выбор сохраняется в аккаунте и этом браузере.','One language across the storefront. Saved to your account and this browser.')}}</p><div class="language-options"><label :class="{chosen:language==='ru'}"><input type="radio" name="language" :checked="language==='ru'" @change="setLanguage('ru')"/><strong>Русский</strong><span>RU</span></label><label :class="{chosen:language==='en'}"><input type="radio" name="language" :checked="language==='en'" @change="setLanguage('en')"/><strong>English</strong><span>EN</span></label></div></div><div class="card preference-block notifications-preference"><span class="preference-icon" aria-hidden="true"><Send :size="25"/></span><p class="eyebrow">TELEGRAM</p><h3>{{tr('Уведомления','Notifications')}}</h3><label class="switch-row"><div><strong>{{tr('Новинки и акции в Telegram','New releases & offers on Telegram')}}</strong><p class="muted">{{tr('Только если Telegram привязан и бот доступен. Можно отключить в любой момент.','Requires a linked Telegram account and an available bot. Turn off at any time.')}}</p></div><input v-model="notifications" type="checkbox" role="switch"/></label></div><div class="settings-save"><button class="primary" :disabled="busy">{{tr('Сохранить настройки','Save settings')}}</button></div></form><TwoFactorStatus :account="account"><button class="security-manage" @click="active='security'">{{tr('Управление защитой и резервными кодами','Manage security & recovery codes')}}</button></TwoFactorStatus></section>
 </div></div></div>
</template>
<style scoped>
.player-panel{width:100%;min-width:0}.player-panel :deep(.desktop-player){margin:0}
/* Account-only reference theme. Shared storefront and Admin remain unchanged. */
.account-page{--ui-bg:#090f16;--ui-surface:#0d151f;--ui-field:#0a1119;--ui-raised:#142131;--ui-control:#536780;--ui-border:#263447;--ui-text:#f4f7fc;--ui-secondary:#b7c4d9;--ui-muted:#9eacc2;--ui-primary:#2473df;--ui-on-primary:#fff;--ui-link:#86bcff;--ui-focus:#76b8ff;--ui-success:#84ebc4;--ui-success-bg:#102c28;--ui-danger:#ffabb7;--ui-radius:8px;--ui-radius-panel:12px;width:100%;max-width:1536px;margin:0 auto;padding:0 32px 48px;color:var(--ui-text);background:#080e14;min-height:calc(100vh - 70px);font-size:16px;isolation:isolate}
